import {allCardInstanceIds,createGame,gameStats,transition,type GameCommand,type GameState} from '@madou/engine';
import {getAction} from '@madou/catalog';
import {assignCharacter,entropy,readySetup,takeCard,trimHand} from './scenario-tools.js';
/** Actual CHANT, two targets and three hits with a checked parry and a physically placed Soldier. */
export function makeR6CombinedDeathScenario(players:{id:string;name:string}[],returnedCounter=false):GameState{
 let s=createGame(players,entropy(),{startingSeat:0});const [a,b,c,d]=players.map(p=>p.id) as [string,string,string,string];assignCharacter(s,a,'侍大将のシン');assignCharacter(s,b,returnedCounter?'早駆けのランカスター':'黒騎士ガーウィン');assignCharacter(s,c,'黒妖精のアーネス');assignCharacter(s,d,'魔導王ガイナス');for(const p of Object.values(s.players))p.permanent={endurance:100,warrior_level:20,spirit:20};
 s.players[b]!.permanent!.warrior_level=(s.players[b]!.permanent!.warrior_level??0)+6-gameStats(s,b).warrior_level;s.players[b]!.damage=gameStats(s,b).endurance-14;s.players[c]!.damage=gameStats(s,c).endurance-18;
 const sword=takeCard(s,a,'天地百撃斬'),counter=takeCard(s,b,returnedCounter?'a2-p10-r3c3':'受け流し'),soldier=takeCard(s,c,'兵士');trimHand(s,a,sword);trimHand(s,b,counter);trimHand(s,c,soldier);s.deck=[...s.deck.filter(id=>getAction(id)!.category!=='open'),...s.deck.filter(id=>getAction(id)!.category==='open')];
 function act(actorId:string,command:GameCommand,dice=Array(100).fill(1)){const input={actorId,command},e={...entropy(),dice},r=transition(s,input,e);if(!r.ok)throw Error(`COMBINED_DEATH_${command.type}_${r.code}`);if(JSON.stringify(r)!==JSON.stringify(transition(JSON.parse(JSON.stringify(s)),input,e)))throw Error('COMBINED_DEATH_REPLAY');s=r.state;const ids=allCardInstanceIds(s);if(ids.length!==220||new Set(ids).size!==220)throw Error('COMBINED_DEATH_CARDS');}
 act(a,{type:'PASS_SETUP'});act(b,{type:'PASS_SETUP'});act(c,{type:'PLACE_INITIAL_FOLLOWER',cardInstanceId:soldier});act(c,{type:'PASS_SETUP'});act(d,{type:'PASS_SETUP'});readySetup(()=>s,id=>act(id,{type:'PASS_SETUP'}));act(a,{type:'START_TURN'});act(a,{type:'CHOOSE_DRAW',draw:false});act(a,{type:'CHANT',cardInstanceId:sword});
 for(let n=0;n<50;n++){const actor=s.seatOrder[s.turnSeat]!;if(s.phase==='action'){if(actor===a)break;act(actor,{type:'PASS_ACTION'});}else if(s.phase==='withdrawal')act(actor,{type:'PASS_WITHDRAWAL'});else if(s.phase==='hand-adjustment')act(actor,{type:'END_TURN',discardIds:s.players[actor]!.hand.slice(0,Math.max(0,s.players[actor]!.hand.length-gameStats(s,actor).handLimit))});else if(s.phase==='turn-start')act(actor,{type:'START_TURN'});else if(s.phase==='draw')act(actor,{type:'CHOOSE_DRAW',draw:false});else throw Error('COMBINED_DEATH_TURN');}
 act(a,{type:'ATTACK',cardInstanceId:sword,targetIds:[b,c],dedicated:true});for(let n=0;n<300;n++){const w=s.windows!.at(-1)!;if(w.kind==='normal-defense')return s;act(w.participants[w.cursor]!,{type:'PASS'},w.kind==='damage'?[3]:Array(100).fill(1));}throw Error('COMBINED_DEATH_WINDOW');
}
